import unittest

from inventory.stock import available, reserve


class Reserve(unittest.TestCase):
    def test_reserve_reduces_stock(self):
        stock = {"tea": 5}
        reserve(stock, "tea", 2)
        self.assertEqual(available(stock, "tea"), 3)

    def test_reserve_refuses_shortfall(self):
        with self.assertRaises(ValueError):
            reserve({"tea": 1}, "tea", 2)
